// Author: Simon-Pierre Boucher — contact@spboucher.ai
// File: Features/Alerts/AlertsSettingsFlow.swift
// Description: The owner's alert settings as the server stores them: one switch per alert type, quiet hours, the hourly cap, thresholds, the outgoing webhook (secret generated by the server and shown once, never kept) and the browsers subscribed to Web Push. Every change is a partial update the server merges; the screen always shows the server's answer, not what was typed.
import Foundation
import SPWalletCore

@MainActor @Observable final class AlertsSettingsFlow {
    let model: AppModel
    private let api: AlertsAPI

    private(set) var view: AlertSettingsView?
    private(set) var loadedAt: Date?
    private(set) var loading = false
    private(set) var saving = false
    var error: String?
    var notice: String?

    // editable copies of the free-form fields (switches are sent at once)
    var quietStart = ""
    var quietEnd = ""
    var quietTz = ""
    var capPerHour = ""
    var thresholds: [String: String] = [:]
    var webhookURL = ""

    // webhook
    /// The secret of the last rotation, in memory only until the owner closes the sheet. Never persisted, never logged.
    private(set) var freshSecret: String?
    private(set) var webhookTest: AlertWebhookTestResult?
    private(set) var webhookBusy = false

    // push devices
    private(set) var subscriptions: [PushSubscription]?
    private(set) var subscriptionsError: String?
    private(set) var pushTest: PushTestResult?
    private(set) var pushBusy = false

    init(model: AppModel) { self.model = model; api = AlertsAPI(model.client) }

    struct ThresholdSpec: Identifiable {
        let key: String; let label: String; let unit: String; let range: ClosedRange<Double>; let integer: Bool; let help: String
        var id: String { key }
    }
    /// Bounds of services/api/src/alerts/store.ts (ThresholdsSchema): checked here to explain a refusal before the server gives it.
    static let thresholdSpecs: [ThresholdSpec] = [
        .init(key: "stuckMinutes", label: "Transfert ou échange non finalisé", unit: "min", range: 5...1440, integer: true, help: "Alerte « bloqué » quand une opération n’est toujours pas finale après ce délai."),
        .init(key: "bridgeStuckMinutes", label: "Pont non finalisé", unit: "min", range: 10...2880, integer: true, help: "Même règle pour un transfert inter-réseaux."),
        .init(key: "agentDigestMinutes", label: "Regroupement des ordres d’agent", unit: "min", range: 0...1440, integer: true, help: "Au plus une notification « ordre exécuté » par agent sur cette durée (0 = une par ordre)."),
        .init(key: "staleBars", label: "Données d’agent périmées", unit: "barres", range: 1...100, integer: true, help: "Nombre de barres manquantes avant l’alerte."),
        .init(key: "signalFailures", label: "Échecs de signal consécutifs", unit: "échecs", range: 1...50, integer: true, help: "Avant l’alerte d’échecs de signal d’un agent."),
        .init(key: "fundingUsd", label: "Paiement de financement", unit: "USD", range: 0...1_000_000, integer: false, help: "Montant absolu à partir duquel un paiement de financement est signalé."),
        .init(key: "diskFreePct", label: "Disque libre du serveur", unit: "%", range: 1...50, integer: false, help: "Alerte quand l’espace libre passe sous ce pourcentage."),
        .init(key: "backupHours", label: "Sauvegarde manquante", unit: "h", range: 1...720, integer: true, help: "Âge maximal de la dernière sauvegarde."),
        .init(key: "feedDebounceSec", label: "Connecteur en panne", unit: "s", range: 30...3600, integer: true, help: "Durée de panne avant l’alerte (un flux qui clignote ne dit rien)."),
        .init(key: "unknownOrderSec", label: "Ordre au sort inconnu", unit: "s", range: 15...3600, integer: true, help: "Délai avant de signaler un ordre dont la plateforme n’a pas confirmé le sort."),
    ]

    func load() async {
        loading = true; defer { loading = false }
        do { adopt(try await api.settings()); error = nil } catch { self.error = model.describe(error) }
        await loadSubscriptions()
    }

    private func adopt(_ v: AlertSettingsView) {
        view = v; loadedAt = Date()
        let s = v.settings
        quietStart = s.quiet.start; quietEnd = s.quiet.end; quietTz = s.quiet.tz
        capPerHour = String(s.capPerHour); webhookURL = s.webhook.url
        let t = s.thresholds
        thresholds = ["stuckMinutes": String(t.stuckMinutes), "bridgeStuckMinutes": String(t.bridgeStuckMinutes), "agentDigestMinutes": String(t.agentDigestMinutes), "staleBars": String(t.staleBars),
                      "signalFailures": String(t.signalFailures), "fundingUsd": Self.plain(t.fundingUsd), "diskFreePct": Self.plain(t.diskFreePct), "backupHours": String(t.backupHours),
                      "feedDebounceSec": String(t.feedDebounceSec), "unknownOrderSec": String(t.unknownOrderSec)]
    }
    private static func plain(_ d: Double) -> String { d == d.rounded() ? String(Int64(d)) : String(d) }
    private static func number(_ s: String) -> Double? { Double(s.trimmingCharacters(in: .whitespaces).replacingOccurrences(of: ",", with: ".")) }

    private func send(_ patch: AlertSettingsPatch, done: String? = nil) async {
        guard model.canOperate, !saving else { return }
        saving = true; defer { saving = false }
        do { adopt(try await api.update(patch)); error = nil; notice = done } catch { self.error = model.describe(error) }
    }

    // MARK: switches

    func setRule(_ kind: AlertKind, on: Bool) async { await send(.rule(kind, on: on)) }
    func setGroup(_ group: AlertGroup, on: Bool) async {
        guard let v = view else { return }
        let rules = Dictionary(uniqueKeysWithValues: v.kinds.filter { $0.group == group && !$0.fixed }.map { ($0.kind.rawValue, on) })
        guard !rules.isEmpty else { return }
        await send(AlertSettingsPatch(rules: rules))
    }
    func setShowDetails(_ on: Bool) async { await send(AlertSettingsPatch(showDetails: on)) }
    func setQuietEnabled(_ on: Bool) async { await send(AlertSettingsPatch(quiet: .init(enabled: on))) }

    // MARK: quiet hours, cap, thresholds

    var quietProblem: String? {
        let hhmm = /^([01]\d|2[0-3]):[0-5]\d$/
        if quietStart.wholeMatch(of: hhmm) == nil || quietEnd.wholeMatch(of: hhmm) == nil { return "Heures au format HH:MM (24 h)." }
        if TimeZone(identifier: quietTz.trimmingCharacters(in: .whitespaces)) == nil { return "Fuseau horaire IANA inconnu (ex. America/Toronto)." }
        return nil
    }
    func saveQuiet() async {
        guard quietProblem == nil else { return }
        await send(AlertSettingsPatch(quiet: .init(start: quietStart, end: quietEnd, tz: quietTz.trimmingCharacters(in: .whitespaces))), done: "Heures calmes enregistrées.")
    }

    var capProblem: String? { guard let n = Int(capPerHour.trimmingCharacters(in: .whitespaces)), (1...500).contains(n) else { return "Entre 1 et 500 par heure." }; return nil }
    func saveCap() async {
        guard capProblem == nil, let n = Int(capPerHour.trimmingCharacters(in: .whitespaces)) else { return }
        await send(AlertSettingsPatch(capPerHour: n), done: "Plafond horaire enregistré.")
    }

    func thresholdProblem(_ spec: ThresholdSpec) -> String? {
        guard let v = Self.number(thresholds[spec.key] ?? ""), spec.range.contains(v), !spec.integer || v == v.rounded() else {
            return "\(spec.integer ? "Entier entre" : "Entre") \(Self.plain(spec.range.lowerBound)) et \(Self.plain(spec.range.upperBound)) \(spec.unit)"
        }
        return nil
    }
    var thresholdsValid: Bool { Self.thresholdSpecs.allSatisfy { thresholdProblem($0) == nil } }
    func saveThresholds() async {
        guard thresholdsValid else { return }
        func i(_ k: String) -> Int? { Self.number(thresholds[k] ?? "").map { Int($0) } }
        var t = AlertSettingsPatch.Thresholds()
        t.stuckMinutes = i("stuckMinutes"); t.bridgeStuckMinutes = i("bridgeStuckMinutes"); t.agentDigestMinutes = i("agentDigestMinutes"); t.staleBars = i("staleBars")
        t.signalFailures = i("signalFailures"); t.fundingUsd = Self.number(thresholds["fundingUsd"] ?? ""); t.diskFreePct = Self.number(thresholds["diskFreePct"] ?? "")
        t.backupHours = i("backupHours"); t.feedDebounceSec = i("feedDebounceSec"); t.unknownOrderSec = i("unknownOrderSec")
        await send(AlertSettingsPatch(thresholds: t), done: "Seuils enregistrés.")
    }

    // MARK: webhook

    var webhookURLProblem: String? {
        let s = webhookURL.trimmingCharacters(in: .whitespaces)
        if s.isEmpty { return nil }
        guard s.count <= 500, let u = URL(string: s), u.scheme == "https", u.host?.isEmpty == false else { return "L’adresse doit être une URL https (500 caractères au plus)." }
        return nil
    }
    func saveWebhookURL() async {
        guard webhookURLProblem == nil else { return }
        await send(AlertSettingsPatch(webhook: .init(url: webhookURL.trimmingCharacters(in: .whitespaces))), done: "Adresse du webhook enregistrée.")
    }
    func setWebhookEnabled(_ on: Bool) async { await send(AlertSettingsPatch(webhook: .init(enabled: on))) }
    func setWebhookDetails(_ on: Bool) async { await send(AlertSettingsPatch(webhook: .init(details: on))) }

    func rotateSecret() async {
        guard model.canOperate, !webhookBusy else { return }
        webhookBusy = true; defer { webhookBusy = false }
        do {
            freshSecret = try await api.rotateWebhookSecret().secret
            if let v = try? await api.settings() { adopt(v) }
            error = nil
        } catch { self.error = model.describe(error) }
    }
    func forgetSecret() { freshSecret = nil }

    func testWebhook() async {
        guard model.canOperate, !webhookBusy else { return }
        webhookBusy = true; webhookTest = nil; defer { webhookBusy = false }
        do { webhookTest = try await api.testWebhook(); error = nil } catch { self.error = model.describe(error) }
    }

    // MARK: Web Push devices (browsers)

    func loadSubscriptions() async {
        do { subscriptions = try await api.pushSubscriptions(); subscriptionsError = nil } catch { subscriptionsError = model.describe(error) }
    }
    func removeSubscription(_ id: String) async {
        guard model.canOperate, !pushBusy else { return }
        pushBusy = true; defer { pushBusy = false }
        do { try await api.deletePushSubscription(id: id); await loadSubscriptions(); notice = "Appareil retiré." } catch { self.error = model.describe(error) }
    }
    func testPush(_ id: String?) async {
        guard model.canOperate, !pushBusy else { return }
        pushBusy = true; pushTest = nil; defer { pushBusy = false }
        do { pushTest = try await api.testPush(id: id); await loadSubscriptions(); error = nil } catch { self.error = model.describe(error) }
    }
}
